import { expect, test, uniqueName } from "../../fixtures";

const W9_PDF = Buffer.from("%PDF-1.4\n% REV-06 w9 sample\n%%EOF\n");
const INSURANCE_PDF = Buffer.from("%PDF-1.4\n% REV-06 insurance sample\n%%EOF\n");
const CONTRACT_PDF = Buffer.from("%PDF-1.4\n% REV-06 contract sample\n%%EOF\n");

test.describe("Review vendors", () => {
  test(
    "Rejecting an extraction requires a note and returns the vendor to the member",
    { tag: "@REV-06" },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor and uploads all three documents.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");

      const createResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("REV06 Vendor"),
          category: "services",
          contact_email: `rev06-${Date.now()}-${Math.random().toString(36).slice(2, 8)}@example.test`,
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = await createResponse.json();
      const vendorId: string = vendor.id;

      const uploads: { kind: string; id: string }[] = [];
      const documents: [string, string, Buffer][] = [
        ["w9", "w9.pdf", W9_PDF],
        ["insurance_certificate", "insurance.pdf", INSURANCE_PDF],
        ["contract", "contract.pdf", CONTRACT_PDF],
      ];
      for (const [kind, filename, buffer] of documents) {
        const uploadResponse = await member.post(`/api/vendors/${vendorId}/documents`, {
          multipart: {
            kind,
            file: { name: filename, mimeType: "application/pdf", buffer },
          },
        });
        expect(uploadResponse.status()).toBe(201);
        const doc = await uploadResponse.json();
        uploads.push({ kind, id: doc.id });
      }

      // Wait until every document has been extracted.
      for (const upload of uploads) {
        await expect
          .poll(
            async () => {
              const r = await member.get(`/api/documents/${upload.id}`);
              return ((await r.json()) as { status: string }).status;
            },
            { timeout: 120_000, intervals: [1_000, 2_000, 3_000] },
          )
          .toBe("extracted");
      }

      // Submit the vendor for review.
      const submitResponse = await member.post(`/api/vendors/${vendorId}/submit`);
      expect(submitResponse.status()).toBe(200);
      expect((await submitResponse.json()).status).toBe("in_review");

      // Locate the W-9 extraction (its id is the one the decision endpoint takes).
      const w9Upload = uploads.find((u) => u.kind === "w9");
      expect(w9Upload).toBeTruthy();
      const extractionResponse = await reviewer.get(`/api/documents/${w9Upload!.id}/extraction`);
      expect(extractionResponse.status()).toBe(200);
      const extraction = await extractionResponse.json();
      expect(extraction.status).toBe("pending_review");
      const extractionId: string = extraction.id;

      // Act + Assert: rejecting without a note is refused.
      const noNoteResponse = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
        data: { decision: "reject" },
      });
      expect(noNoteResponse.status()).toBe(422);

      // Act: rejecting with a note succeeds.
      const rejectResponse = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
        data: { decision: "reject", note: "Tax ID does not match" },
      });
      expect(rejectResponse.status()).toBe(200);
      const rejected = await rejectResponse.json();
      expect(rejected.status).toBe("rejected");
      expect(rejected.review_note).toBe("Tax ID does not match");

      // Vendor returns to the member as rejected.
      const vendorResponse = await member.get(`/api/vendors/${vendorId}`);
      expect(vendorResponse.status()).toBe(200);
      expect((await vendorResponse.json()).status).toBe("rejected");

      // Audit trail records the rejection.
      const auditResponse = await reviewer.get(`/api/vendors/${vendorId}/audit`);
      expect(auditResponse.status()).toBe(200);
      const audit = (await auditResponse.json()) as { items: { action: string }[] };
      expect(audit.items.map((event) => event.action)).toContain("extraction.rejected");
    },
  );
});
